              detail: `$a^2 + b^2 = ${lhs}$、$c^2 = ${rhs}$`,
              message:
                "数式としては一致していますが、辺の長さなので正の整数で考えるのがふつうです。",
              hint: "正の整数で試してみよう。",
              canonicalKey: key,
              trivial: true,
