    meaning: `**「どちらか一方」で同時に起こらないとき、総数はたし算——それが和の法則。**

あることの起こり方が、$A$ の場合（$m$ 通り）と $B$ の場合（$n$ 通り）に分かれ、$A$ と $B$ が**同時に起こらない**なら、総数は $m + n$ 通りです。[樹形図] でいえば、続けて伸びる $1$ 本の木ではなく、横に並ぶ別々の木。使う前に「**すべての場合を尽くしているか**」「**同時に起こることはないか**」の $2$ つを必ず確かめます。

**数値で確かめる（低い床）**：入る部活を $1$ つだけ決めるとき、運動部 $6$ 種類・文化部 $4$ 種類のどちらか一方に入る（かけもちなし）なら、$2$ つは同時に起こらない別々の木なので $6 + 4 = 10$ 通り。場合分けが $3$ つに増えても、どれも同時に起こらないかぎり同じように足します。

────────

**もっと深く**：$1$ つの問題の中に「続けて起こる所（[積の法則]）」と「場合に分かれる所（和の法則）」が同居することがあります。たとえば経路の問題では、各ルートの中は積で数え、ルートどうしは同時に起こらないので和で束ねます。「足すのか、かけるのか」で迷ったら、問題の言葉ではなく [樹形図] が続けて伸びるか別々の木に分かれるかを見る——これが取り違えを防ぐいちばんの薬です。`,
