    scenes: `- **戻さないくじ引き**：$1$ 本目を引いて戻さないと、$2$ 本目を測る全体が縮む——$1$ 本目の結果で $2$ 本目の確率が変わる
- **時間順でない情報**：$2$ 個のサイコロで「少なくとも $1$ 個は $5$」と分かると、$36$ 通りの全体がその情報を満たす通りだけに縮む
- **独立の判定**：$P_A(B)$ と $P(B)$ を計算して比べ、一致すれば独立——縮めても割合が変わらない`,
